Ext.define('BNK.view.BackOffice.bom.BomTasPushSettingMViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BomTasPushSettingMViewController',

    config: {
        viewId: 'BomTasPushSettingM'
    },

    /* 푸시 수신여부 조회 */
    getRecvYn: function(msgDvcd, msgDvnm) {
        // Deferred 성공시 resolve 처리, 실패시 reject 처리
        var me = this,
            D = new Ext.Deferred();

        Ext.Ajax.request({
        	headers: {
        		viewId: me.getViewId(),
        		serviceId: 'BomTasSvc.findOnePushSetting'
        	},
        	jsonData : {
                msgDvcd : msgDvcd,
                msgDvnm : msgDvnm
            },
        	scope : me,
            async : false,
        	success : function(res) {
        		var responseText = Ext.JSON.decode(res.responseText);
                D.resolve(responseText.result);
            }
        // 	},
        // 	failure: function(response, opts) {
        // 		D.reject(me);
        // 	}
        });

        return D.promise;
    },

    /* 푸시 알림설정 저장 */
    onBtnSaveTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            rcvDenyStrtm = refs.rcvDenyStrtm.getValue(),
            rcvDenyEdtm = refs.rcvDenyEdtm.getValue(),
            param = {
                rcvDenyStrtm : Ext.Date.format(rcvDenyStrtm, 'His'),
                rcvDenyEdtm : Ext.Date.format(rcvDenyEdtm, 'His'),
            };

        for(var i in refs.items.items.items) {
            var ctrl = refs.items.items.items[i].controller;
            param.msgDvcd = ctrl.getMsgDvcd();
            param.recvYn = ctrl.getRecvYn();

            Ext.Ajax.request({
                headers: {
                    viewId : me.getViewId(),
                    serviceId : 'BomTasSvc.saveOnePushSetting'
                },
                jsonData : param,
                scope : me,
                async : false,
                success : function(response) {
                    var res = Ext.JSON.decode(response.responseText);
                }
            });
        }

        var home = this.getView().up(Property.ROUTE_HOME),
            naviView = home.lookup('NaviView'),
            backButton = naviView.getNavigationBar().getBackButton();

        backButton.onTap();	// 뒤로가기
    },

    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            code = 'TAS004',
            codeStore = Ext.StoreMgr.get('CodeStore'),
            items = codeStore.getData().items,
            pushSetting = [];

        for (var i = 0, l = items.length; i < l; i++) {
            if (code === items[i].data.code) {
                var children = items[i].data.children;
                for (var j = 0, l2 = children.length; j < l2; j++) {
                    var text = children[j].text,
                        value = children[j].value;

                    // 메시지구분 코드 && 명
                    if (text && value) {
                        me.getRecvYn(value, text).then(function(result) {
                            if (result && result.msgDvcd && result.msgDvnm && result.recvYn) {
                                var msgDvcd = result.msgDvcd,
                                    msgDvnm = result.msgDvnm,
                                    recvYn = result.recvYn,
                                    recvYnVal = (recvYn == 'Y') ? 1 : 0,		// 수신여부
                                    rcvDenyStrtm = (result.rcvDenyStrtm) ? result.rcvDenyStrtm : "000000", 	// 수신거부 시작시간
                                    rcvDenyEdtm = (result.rcvDenyEdtm) ? result.rcvDenyEdtm : "000000",		// 수신거부 종료시간
                                    now = new Date();

                                refs.rcvDenyStrtm.setValue(new Date(now.getYear(), now.getMonth(), now.getDate(), rcvDenyStrtm.substr(0,2), rcvDenyStrtm.substr(2,2), rcvDenyStrtm.substr(4,2), 0));
                                refs.rcvDenyEdtm.setValue(new Date(now.getYear(), now.getMonth(), now.getDate(), rcvDenyEdtm.substr(0,2), rcvDenyEdtm.substr(2,2), rcvDenyEdtm.substr(4,2), 0));

                                pushSetting.push({
                                    msgDvnm : msgDvnm,
                                    msgDvcd : msgDvcd,
                                    recvYn : recvYn
                                });

                                // 아이템 추가
                                refs.items.add(Ext.create('BomTasPushSettingItemsM', {
                                    msgDvnm : msgDvnm,
                                    msgDvcd : msgDvcd,
                                    recvYnVal : recvYnVal
                                }));
                            }
                        });
                    }
                }
            }
        }

        vm.set('pushSetting', pushSetting);
    }

});